function probe() {
    var java = this.java;
    var source = this.source;

    try {
        if (typeof java.showReadingBrowser == 'function') {
            return "ios";
        }
    } catch (e) {}

    try {
        if (typeof java.reLoginView == 'function') {
            return "panel";
        }
        new Packages.io.legado.kazusa.utils.TimeoutCancellationException('');
        return "panel";
    } catch (e) {}

    try {
        if (typeof source.loginUi == 'function') {
            return "browser";
        }
    } catch (e) {}

    return "panel";
}

function openReview(url, sources, ident) {
    var java = this.java;
    if (ident == null) ident = '段评';
    var rt = this.probe();
    if (rt == "panel") {
        var htmlContent = '';
        try {
            htmlContent = java.ajax(url);
        } catch (e) {}
        try {
        java.showBrowser(
            url,
            htmlContent,
            'window.java=java;',
            JSON.stringify({
                "expandedCornersRadius": 20,
                "dismissOnTouchOutside": true,
                "isDraggable": true,
                "shouldDimBackground": true,
                "backgroundDimAmount": 0.5,
                "hardwareAccelerated": true,
                "isNestedScrollingEnabled": true,
                "isGestureInsetBottomIgnored": true,
                "setFitToContents": true,
                "isHideable": true,
                "heightPercentage": 0.8
            })
        );
        } catch (e) {
            java.startBrowser(url, sources + ident);
        }
    } else {
        try { java.showReadingBrowser(url, sources + ident); return; } catch (e) {}
        java.startBrowser(url, sources + ident);
    }
}

function godOpen(u, t) { try { java.showReadingBrowser(u, t); return; } catch (e) {} try { java.startBrowser(u, t); } catch (e) {} }

loginUrl:
function login(flag){
  if(flag===undefined){
    try{ result=JSON.parse(source.getLoginInfo()||'{}'); }catch(e){ result={}; }
  }else{
    try{ source.putLoginInfo(JSON.stringify(result)); result=JSON.parse(source.getLoginInfo()||'{}'); }catch(e){ result={}; }
  }
  var email=String(result['邮箱']||'');
  var pwd=String(result['密码']||'');
  if(!email||!pwd){ java.longToast('请填写邮箱和密码'); throw '请填写邮箱和密码'; }
  var hh='';try{hh=String((JSON.parse(source.getVariable()||'{}')||{}).host||'').trim();}catch(e){}
  if(!hh){ try{ hh=String(result['线路']||'').trim(); }catch(e){} }
  if(!hh){ hh=(typeof host!=='undefined')?host:''; }
  if(hh.indexOf('http')!=0){ hh='http://'+hh; }
  var opt=JSON.stringify({method:'POST',body:JSON.stringify({email:email,password:pwd}),headers:{'Content-Type':'application/json'}});
  java.longToast('正在登录…');
  var resp=java.ajax(hh+'/legado/login,'+opt);
  var j=JSON.parse(resp);
  if(j && j.code==200 && j.data && j.data.token){
    var vv={};try{vv=JSON.parse(source.getVariable()||'{}');}catch(e){}
    vv.token=j.data.token; vv.host=hh;
    source.setVariable(JSON.stringify(vv));
    java.longToast('登录成功'+((j.data.user&&j.data.user.nickname)?('：'+j.data.user.nickname):''));
  }else{
    var em=(j&&j.msg)||'登录失败'; java.longToast(em); throw em;
  }
}

