        let date2 = new Date().getTime();
        let t = date2 - date1;
        let c = String(html).indexOf('书山');
        let time = t / 1000 + 's';
        let logTime = '【' + currentHost + '】\n┋┋\n' + '解析时间：' + time;

        if (c == -1 || t > 5000) {
            java.longToast('\n💔【访问失败提示】\n' + '┏┅━┅━┅━┅━┅┅━┅━┅┓\n┋┋\n' + logTime + '\n┋┋\n♣️当前接口无法访问(可能被墙)♣️\n┋┋\n请切换其他接口/切换网络环境\n┋┋' + '\n┗┅━┅━┅━┅━┅┅━┅━┅┛');
        } else if (t < 1000) {
