    --ink-2:#6b5765;
    --ink-3:#9b8b98;
    --line:rgba(190,150,170,.2);
}

html,body{height:100%}

body{
    font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif;
    color:var(--ink-1);
    min-height:100vh;
    padding:18px 14px 32px;
    position:relative;
    overflow-x:hidden;
    background:#fdf6f8;
}

.bg-layer{
    position:fixed;inset:0;z-index:0;pointer-events:none;
    background:
        radial-gradient(680px 420px at 8% -6%, rgba(255,205,220,.85), transparent 60%),
        radial-gradient(720px 460px at 98% 4%, rgba(255,224,190,.7), transparent 62%),
        radial-gradient(700px 500px at 50% 108%, rgba(214,182,255,.35), transparent 60%),
        linear-gradient(180deg,#fff8fa 0%,#fdf3f6 45%,#f9edf2 100%);
}

#bubbles{
    position:fixed;inset:0;z-index:1;pointer-events:none;overflow:hidden;
}

.bubble{
    position:absolute;
    bottom:-120px;
    border-radius:50%;
    background:radial-gradient(circle at 30% 30%, rgba(255,255,255,.95), rgba(255,255,255,.15) 60%, rgba(255,220,230,.35) 100%);
    box-shadow:
        0 0 12px rgba(255,220,230,.6),
        0 0 24px rgba(240,180,200,.25),
        inset -3px -5px 8px rgba(240,180,200,.25),
        inset 4px 6px 10px rgba(255,255,255,.9);
    animation:rise linear infinite;
    will-change:transform,opacity;
}

@keyframes rise{
    0%{transform:translate3d(0,0,0) scale(.6);opacity:0;}
    10%{opacity:.9;}
    35%{transform:translate3d(var(--drift),-38vh,0) scale(1);}
    65%{transform:translate3d(calc(var(--drift) * -0.7), -68vh, 0) scale(1.05);}
    90%{opacity:.7;}
    100%{transform:translate3d(var(--drift),-115vh,0) scale(1.1);opacity:0;}
}

.wrap{
    position:relative;z-index:2;
    width:100%;max-width:640px;margin:0 auto;
    background:rgba(255,250,252,.72);
    backdrop-filter:blur(28px) saturate(160%);
    -webkit-backdrop-filter:blur(28px) saturate(160%);
    border-radius:28px;
    border:1px solid rgba(255,255,255,.9);
    box-shadow:
        0 30px 60px -28px rgba(200,120,150,.45),
        0 12px 30px -18px rgba(180,140,180,.35),
        0 1px 0 rgba(255,255,255,.9) inset;
    overflow:hidden;
    animation:riseIn .7s cubic-bezier(.22,.61,.36,1);
}
@keyframes riseIn{from{opacity:0;transform:translateY(20px) scale(.985)}to{opacity:1;transform:none}}

.head{
    position:relative;
    padding:28px 24px 20px;
    text-align:center;
    background:
        radial-gradient(120% 150% at 50% -30%, rgba(255,214,224,.85), transparent 65%),
        linear-gradient(180deg, rgba(255,255,255,.6), transparent);
}
.head::after{
    content:'';
    position:absolute;left:50%;bottom:0;
    width:180px;height:1px;transform:translateX(-50%);
    background:linear-gradient(90deg,transparent,var(--line) 30%,var(--line) 70%,transparent);
}

.head-orn{
