<script>
var TYPE_LABEL = { novel:'小说', audio:'听书', comic:'漫画', video:'视频' };

function switchTab(t){
    document.querySelectorAll('.tab-btn').forEach(function(b){
        b.classList.toggle('active', b.getAttribute('data-tab') == t);
    });
    document.querySelectorAll('.panel').forEach(function(p){
        p.classList.toggle('active', p.id == 'panel-' + t);
    });
}

function pickGender(g){
    document.querySelectorAll('.gender-btn').forEach(function(b){
        b.classList.toggle('active', b.getAttribute('data-gender') == g);
    });
    document.getElementById('gender-output').textContent = g;
}

function pick(el){
    var isAll = el.getAttribute('data-all') == '1';
    if (isAll) {
        if (el.classList.contains('selected')) {
            el.classList.remove('selected');
        } else {
            document.querySelectorAll('.src-card').forEach(function(c){ c.classList.remove('selected'); });
            el.classList.add('selected');
        }
    } else {
        document.querySelectorAll('.all-card').forEach(function(c){ c.classList.remove('selected'); });
        el.classList.toggle('selected');
    }
    updateOutput();
}

function updateOutput(){
    var allSel = document.querySelector('.all-card.selected');
    var valEl = document.getElementById('current-value');
    var cntEl = document.getElementById('current-count');

    if (allSel) {
        var t = allSel.getAttribute('data-type');
        document.getElementById('result-output').textContent = '__ALL__' + t;
        valEl.textContent = TYPE_LABEL[t] + ' · 全部';
        cntEl.textContent = 'ALL';
        return;
    }
    var names = [];
    document.querySelectorAll('.src-card.selected').forEach(function(c){
        var n = c.getAttribute('data-name');
        if (n) names.push(n);
    });
    document.getElementById('result-output').textContent = names.join(',');
    valEl.textContent = names.length ? names.join('、') : '未选择';
    cntEl.textContent = names.length;
}

function clearAll(){
    document.querySelectorAll('.src-card').forEach(function(c){ c.classList.remove('selected'); });
    updateOutput();
}

(function spawnBubbles(){
    var box = document.getElementById('bubbles');
    if (!box) return;
    var count = 18;
    for (var i = 0; i < count; i++) {
        var b = document.createElement('span');
        b.className = 'bubble';
        var size = 10 + Math.random() * 26;
        b.style.width = size + 'px';
        b.style.height = size + 'px';
        b.style.left = (Math.random() * 100) + '%';

        var drift = (Math.random() * 80 - 40).toFixed(1) + 'px';
        b.style.setProperty('--drift', drift);

        var dur = (10 + Math.random() * 12).toFixed(2) + 's';
        b.style.animationDuration = dur;
        b.style.animationDelay = (-Math.random() * dur.replace('s','')) + 's';

        var o = (0.35 + Math.random() * 0.4).toFixed(2);
        b.style.setProperty('opacity', o);

        box.appendChild(b);
    }
})();
</script>
</body>
