let b64 = String(baseUrl);
let prefix = 'data:chapterUrl;base64,';
if (b64.indexOf(prefix) === 0) {
    b64 = b64.substring(prefix.length);
}
let commaIdx = b64.indexOf(',');
if (commaIdx >= 0) {
    b64 = b64.substring(0, commaIdx);
}

let chapterParams = JSON.parse(java.base64Decode(b64));

nid = String(chapterParams.novelId || '');
cid = String(chapterParams.chapterId || '');

token = java.base64Decode(JJtoken());
enbody = String(Date.now())+":"+token+":"+nid;
sign = encode(enbody);
body = "versionCode=444&novelId="+nid+"&chapters="+cid+"&orderType=15&isautoBuy=0&autosubscribeStatus=0&notUseBackpoint=&sign="+sign;
url = "https://android.jjwxc.net/androidapi/buy,";
post = {
    "method": "POST",
    "body": String(body)
};
