    java.longToast(JSON.parse(a).message);
    result = true;
} else {
    mm = JSON.parse(a).message == "" 
        ? JSON.parse(a).popupdata.popupmessage + "\n❗️进晋江app进行一次验证后❗️才能在阅读app使用购买功能" 
        : JSON.parse(a).message;
    java.longToast(mm);
