ruleContent.subContent:
@js:
let chapterParams = JSON.parse(java.hexDecodeToString(result));
let source = chapterParams.source;
let bookId = chapterParams.book_id || '';
let itemId = chapterParams.item_id || '';

const sourceConfig = {
    '番茄听书': { source: null, params: { item_id: itemId, tone_id: getTtsTone('fanqie'), book_id: bookId } },
    '番茄畅听': { source: null, params: { item_id: itemId, tone_id: getTtsTone('fanqie'), book_id: bookId } },
    '七猫听书': { source: 'qm', params: { book_id: bookId, item_id: itemId }, require: ['bookId', 'itemId'] },
    '酷我听书': { source: 'kw', params: { item_id: itemId }, require: ['itemId'] },
};

let cfg = sourceConfig[source];
let apiUrl = '';

if (cfg) {
    let ok = !cfg.require || cfg.require.every(k => ({ bookId, itemId })[k]);
    if (ok) {
        let query = Object.entries(cfg.params)
            .filter(([, v]) => v !== '' && v != null)
            .map(([k, v]) => `${k}=${v}`)
            .join('&');
        if (cfg.source) query = `source=${cfg.source}&` + query;
        apiUrl = getServerHost() + '/audio_lrc?' + query;
    }
}

if (apiUrl) {
    try {
        result = decode(java.ajax(apiUrl));
    } catch (e) {
        result = '';
    }
} else {
    result = '';
}

